begin;
create or replace function public.start_learning_session(p_assignment uuid,p_idempotency text)returns public.learning_sessions language plpgsql security definer set search_path=''as $$
declare a public.assignments;e public.class_enrollments;r public.learning_sessions;begin select*into a from public.assignments where id=p_assignment and state='active'and(available_from is null or available_from<=now())and(due_at is null or due_at>=now());if a.id is null then raise exception'assignment unavailable';end if;select*into e from public.class_enrollments where class_id=a.class_id and learner_id=auth.uid()and status='active';if e.id is null then raise exception'forbidden'using errcode='42501';end if;insert into public.learning_sessions(organization_id,assignment_id,learner_id,lesson_version_id,state,idempotency_key,started_at)values(a.organization_id,a.id,auth.uid(),a.lesson_version_id,'in_progress',p_idempotency,now())on conflict(assignment_id,learner_id)do update set updated_at=now()returning*into r;insert into public.audit_events(organization_id,actor_id,event_type,aggregate_type,aggregate_id)select a.organization_id,auth.uid(),'learning.session_started','learning_session',r.id where not exists(select 1 from public.audit_events x where x.organization_id=a.organization_id and x.actor_id=auth.uid()and x.event_type='learning.session_started'and x.aggregate_id=r.id);return r;end$$;

create or replace function public.submit_assessment(p_assignment uuid,p_idempotency text,p_responses jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
declare a public.assignments;e public.class_enrollments;attempt public.assessment_attempts;objective uuid;earned numeric:=0;possible numeric:=0;outcomes jsonb;decision public.mastery_decisions;ratio numeric;next_state public.mastery_state;kind text;begin if jsonb_typeof(p_responses)<>'array'or jsonb_array_length(p_responses)>200 then raise exception'invalid response payload';end if;select*into a from public.assignments where id=p_assignment and state='active'and(available_from is null or available_from<=now())and(due_at is null or due_at>=now());if a.id is null then raise exception'assignment unavailable';end if;select*into e from public.class_enrollments where class_id=a.class_id and learner_id=auth.uid()and status='active';if e.id is null then raise exception'forbidden'using errcode='42501';end if;select*into attempt from public.assessment_attempts where organization_id=a.organization_id and idempotency_key=p_idempotency;if attempt.id is not null then return jsonb_build_object('attemptId',attempt.id,'replayed',true);end if;if(select count(*)from public.assessment_attempts x where x.assignment_id=a.id and x.learner_id=auth.uid())>=a.attempt_limit then raise exception'attempt limit reached';end if;insert into public.assessment_attempts(organization_id,assignment_id,learner_id,assessment_version_id,state,idempotency_key,responses,submitted_at,finalized_at)values(a.organization_id,a.id,auth.uid(),a.assessment_version_id,'scored',p_idempotency,p_responses,now(),now())returning*into attempt;with scored as(select i.id,i.points,case when response_value->>'option'=i.answer_key->>'correctOption'then i.points else 0 end got from public.assessment_items i left join lateral(select value response_value from jsonb_array_elements(p_responses)where value->>'itemId'=i.id::text limit 1)x on true where i.assessment_version_id=a.assessment_version_id),agg as(select coalesce(sum(got),0)earned_total,coalesce(sum(points),0)possible_total,jsonb_agg(jsonb_build_object('itemId',id,'earned',got,'possible',points))outcome_rows from scored)select earned_total,possible_total,outcome_rows into earned,possible,outcomes from agg;insert into public.assessment_scores(organization_id,attempt_id,scoring_version,earned,possible,outcomes)values(a.organization_id,attempt.id,'1.0',earned,possible,outcomes);select objective_id into objective from public.assessment_versions where id=a.assessment_version_id;ratio=case when possible=0 then 0 else earned/possible end;next_state=case when ratio>=.9 then'advanced'::public.mastery_state when ratio>=.75 then'proficient'::public.mastery_state when ratio>=.5 then'developing'::public.mastery_state else'emerging'::public.mastery_state end;kind=case when ratio>=.75 then'enrichment'else'remediation'end;insert into public.mastery_decisions(organization_id,learner_id,objective_id,attempt_id,previous_state,new_state,ratio,policy_version,evidence,explanation)values(a.organization_id,auth.uid(),objective,attempt.id,'not_assessed',next_state,ratio,'1.0',jsonb_build_object('score',earned,'possible',possible),earned||' of '||possible||' points')returning*into decision;insert into public.learning_recommendations(organization_id,learner_id,objective_id,mastery_decision_id,kind,reason)values(a.organization_id,auth.uid(),objective,decision.id,kind,case when kind='enrichment'then'Mastery threshold met'else'Mastery threshold not met'end);insert into public.audit_events(organization_id,actor_id,event_type,aggregate_type,aggregate_id,data)values(a.organization_id,auth.uid(),'assessment.scored','assessment_attempt',attempt.id,jsonb_build_object('scoringVersion','1.0'));return jsonb_build_object('attemptId',attempt.id,'earned',earned,'possible',possible,'mastery',next_state,'recommendation',kind,'replayed',false);end$$;
commit;
